mapper.select:
SELECT v.* FROM (SELECT a.fin_statement_hd_id, a.fin_statement_templet_hd_id, a.company_id, a.bp_id, a.fiscal_year, a.fiscal_year year, a.fiscal_month, b.fin_statement_templet_name, a.currency_code, a.CREATION_DATE FROM hls_fin_statement_hd a LEFT JOIN hls_fin_statement_tmplt_hd b ON a.fin_statement_templet_hd_id=b.fin_statement_templet_hd_id) v
v.bp_id=#{bpId}
AND v.fiscal_year=#{fiscalYear}
AND v.fiscal_month=#{fiscalMonth}
AND v.bp_id in (SELECT ppt.tenant_bp_id FROM prj_project_tenant ppt WHERE ppt.project_id = #{projectId})
AND v.bp_id IN ( SELECT ppg.guarantor_bp_id FROM prj_project_guarantor ppg WHERE ppg.project_id = #{projectId} )
ORDER BY fin_statement_hd_id DESC

SELECT * FROM hls_fin_statement_hd hfsh WHERE hfsh.bp_id = #{bpId}
AND hfsh.company_id = #{companyId}
ORDER BY hfsh.fiscal_year,hfsh.fiscal_month

SELECT * FROM hls_fin_statement_hd hfsh
1 = 1 and hfsh.fiscal_year is not null
AND hfsh.header_id = #{headerId}
and hfsh.bp_id = #{bpId}
ORDER BY hfsh.fiscal_year

mapper.update:
UPDATE
    hls_fin_statement_hd a
SET
    a.check_status = #{checkStatus}
WHERE
    a.bp_id = #{bpId}
AND a.header_id=#{headerId}
and a.fin_statement_templet_hd_id = #{finStatementTempletHdId}

UPDATE
    hls_fin_statement_hd a
SET
    a.header_id = null
WHERE
    a.bp_id = #{bpId}
AND a.header_id=#{headerId}
and a.fin_statement_templet_hd_id = #{finStatementTempletHdId}

mapper.delete:
DELETE FROM
      hls_fin_statement_hd
where bp_id = #{bpId}
    and fin_statement_templet_hd_id = #{finStatementTempletHdId}
    and header_id = #{headerId}

mapper.select:
SELECT a.report_year report_year FROM hls_fin_statement_hd a ,hls_fin_statement_tmplt_hd b
a.fin_statement_templet_hd_id=b.fin_statement_templet_hd_id
and a.bp_id=#{bpId}
and a.header_id = #{headerId}
ORDER BY fiscal_year
